const tabId = 1148881640;

const candidateUrls = [
  "https://cookpad.com/eng/recipes/463677",
  "https://cookpad.com/eng/recipes/349259",
  "https://cookpad.com/eng/recipes/5334073",
  "https://cookpad.com/eng/recipes/8910946",
  "https://cookpad.com/eng/recipes/13653960"
];

const results = [];

for (const url of candidateUrls) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

  const data = await browserjs(tabId, () => {
    const title = document.querySelector('h1')?.textContent?.trim();
    const author = document.querySelector('[data-recipe-author-name], .author, a[href*="/users/"]')?.textContent?.trim();
    const description = document.querySelector('meta[name="description"]')?.content || document.querySelector('.description, [data-recipe-description]')?.textContent?.trim();

    const ingredientNodes = Array.from(document.querySelectorAll('[data-ingredient-name], .ingredient, li[id*="ingredient"], .ingredient-list li'));
    const ingredients = ingredientNodes.map(n => n.textContent?.trim()).filter(Boolean);

    const stepNodes = Array.from(document.querySelectorAll('[data-step-instruction], .step, li[id*="step"], ol.steps li, .step-instruction'));
    const steps = stepNodes.map(n => n.textContent?.trim()).filter(Boolean);

    return {
      title,
      author,
      description,
      ingredients,
      steps
    };
  });

  results.push({ url, ...data });
}

console.log("Scraped candidates count:", results.length);
for (const r of results) {
  console.log(`URL: ${r.url}`);
  console.log(`TITLE: ${r.title}`);
  console.log(`AUTHOR: ${r.author}`);
  console.log(`INGREDIENTS: ${JSON.stringify(r.ingredients)}`);
  console.log(`STEPS COUNT: ${r.steps?.length}`);
  console.log('---');
}

